    required this.paidCount,
    required this.recentTransactions,
  });

  /// Membaca dari JSON (snake_case). Properti yang belum dikenal diabaikan (kompatibilitas maju).
  factory DashboardPayments.fromJson(Map<String, Object?> json) {
    return DashboardPayments(
      awaitingReviewCount: readField(json, 'awaiting_review_count', decodeInt),
      awaitingReviewByType: readField(json, 'awaiting_review_by_type', (Object? v0) => DashboardPaymentTypeCounts.fromJson(decodeObject(v0))),
      oldestSubmittedAt: readOptionalField(json, 'oldest_submitted_at', decodeDateTime),
      overdueCount: readField(json, 'overdue_count', decodeInt),
      overdueByType: readField(json, 'overdue_by_type', (Object? v0) => DashboardPaymentTypeCounts.fromJson(decodeObject(v0))),
      awaitingTransferCount: readField(json, 'awaiting_transfer_count', decodeInt),
      adjustmentsPendingCount: readField(json, 'adjustments_pending_count', decodeInt),
      adjustmentsOverdueCount: readField(json, 'adjustments_overdue_count', decodeInt),
      paidTotalAmount: readField(json, 'paid_total_amount', decodeString),
      paidCount: readField(json, 'paid_count', decodeInt),
      recentTransactions: readField(json, 'recent_transactions', (Object? v0) => decodeList(v0, (Object? v1) => DashboardTransaction.fromJson(decodeObject(v1)))),
    );
  }

  /// Payment pending yang buktinya sudah dikirim dan siap diputus (= AdminPaymentSummary.awaiting_review_count,
  /// total filter stage=awaiting_review).
  final int awaitingReviewCount;

  final DashboardPaymentTypeCounts awaitingReviewByType;

  /// Waktu kirim bukti tertua di antrean; null bila antrean kosong.
  final DateTime? oldestSubmittedAt;

  /// Bagian awaiting_review yang lewat `review_due_at` (= AdminPaymentSummary.overdue_count dan total filter
  /// stage=awaiting_review&overdue=true), mencakup iuran dan tiket (aturan di deskripsi operasi).
  final int overdueCount;

  /// Rincian overdue_count per jenis; jumlahnya sama dengan overdue_count. `ticket` adalah bukti tiket yang
  /// dieskalasi, bukan dibatalkan otomatis (D5, PRD 3.9).
  final DashboardPaymentTypeCounts overdueByType;

  /// Payment pending yang belum memiliki bukti (= AdminPaymentSummary.awaiting_transfer_count; informasi,
  /// bukan antrean keputusan).
  final int awaitingTransferCount;

  /// Penyesuaian refund/koreksi berstatus pending (= AdminPaymentSummary.adjustments_pending_count, D6).
  final int adjustmentsPendingCount;

  /// Penyesuaian pending yang lewat `due_at` (= AdminPaymentSummary.adjustments_overdue_count, D6); bagian
  /// "antrean terlambat" PRD 3.15.
  final int adjustmentsOverdueCount;

  /// Kartu "Total Transaksi" - jumlah bruto seluruh payment paid, sebelum penyesuaian/refund.
  final Money paidTotalAmount;

  final int paidCount;

  /// Payment paid terbaru menurut waktu keputusan, maksimal 10.
  final List<DashboardTransaction> recentTransactions;

  /// Menulis ke JSON (snake_case); field opsional yang kosong tidak dikirim.
  Map<String, Object?> toJson() => <String, Object?>{
    'awaiting_review_count': awaitingReviewCount,
    'awaiting_review_by_type': awaitingReviewByType.toJson(),
    'oldest_submitted_at': encodeNullable(oldestSubmittedAt, (v) => encodeDateTime(v)),
    'overdue_count': overdueCount,
    'overdue_by_type': overdueByType.toJson(),
    'awaiting_transfer_count': awaitingTransferCount,
    'adjustments_pending_count': adjustmentsPendingCount,
    'adjustments_overdue_count': adjustmentsOverdueCount,
    'paid_total_amount': paidTotalAmount,
    'paid_count': paidCount,
    'recent_transactions': [for (final e0 in recentTransactions) e0.toJson()],
  };

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is DashboardPayments &&
          other.awaitingReviewCount == awaitingReviewCount &&
          other.awaitingReviewByType == awaitingReviewByType &&
          other.oldestSubmittedAt == oldestSubmittedAt &&
          other.overdueCount == overdueCount &&
          other.overdueByType == overdueByType &&
          other.awaitingTransferCount == awaitingTransferCount &&
          other.adjustmentsPendingCount == adjustmentsPendingCount &&
          other.adjustmentsOverdueCount == adjustmentsOverdueCount &&
          other.paidTotalAmount == paidTotalAmount &&
          other.paidCount == paidCount &&
          deepEquals(other.recentTransactions, recentTransactions);

  @override
  int get hashCode => Object.hashAll(<Object?>[awaitingReviewCount, awaitingReviewByType, oldestSubmittedAt, overdueCount, overdueByType, awaitingTransferCount, adjustmentsPendingCount, adjustmentsOverdueCount, paidTotalAmount, paidCount, deepHash(recentTransactions)]);

  @override
  String toString() => 'DashboardPayments(awaitingReviewCount: $awaitingReviewCount, awaitingReviewByType: $awaitingReviewByType, oldestSubmittedAt: $oldestSubmittedAt, overdueCount: $overdueCount, overdueByType: $overdueByType, awaitingTransferCount: $awaitingTransferCount, adjustmentsPendingCount: $adjustmentsPendingCount, adjustmentsOverdueCount: $adjustmentsOverdueCount, paidTotalAmount: $paidTotalAmount, paidCount: $paidCount, recentTransactions: $recentTransactions)';
}

