      userId: readField(json, 'user_id', decodeString),
      fullName: readField(json, 'full_name', decodeString),
      avatarUrl: readOptionalField(json, 'avatar_url', decodeString),
      cohort: readField(json, 'cohort', decodeInt),
      cohortCode: readField(json, 'cohort_code', decodeString),
      city: readOptionalField(json, 'city', decodeString),
      profession: readOptionalField(json, 'profession', (Object? v0) => NetworkMasterRef.fromJson(decodeObject(v0))),
      professions: readField(json, 'professions', (Object? v0) => decodeList(v0, decodeString)),
      latestEducation: readOptionalField(json, 'latest_education', (Object? v0) => NetworkEducationEntry.fromJson(decodeObject(v0))),
      lastEducationInstitution: readOptionalField(json, 'last_education_institution', decodeString),
      lastEducationCity: readOptionalField(json, 'last_education_city', decodeString),
      skills: readField(json, 'skills', (Object? v0) => decodeList(v0, (Object? v1) => NetworkMasterRef.fromJson(decodeObject(v1)))),
    );
  }

  final String userId;

  final String fullName;

  /// URL avatar (publik atau bertanda tangan maksimal 10 menit, PRD 5.4); null bila tidak ada.
  final String? avatarUrl;

  final int cohort;

  /// Kode angkatan, format sama dengan MemberCard.cohort_code; UI dapat menampilkannya sebagai tagar.
  final String cohortCode;

  final String? city;

  /// Deprecated (aplikasi 1.0.0); pakai `professions`. Profesi pertama yang tertaut master.
  final NetworkMasterRef? profession;

  /// Profesi sesuai urutan pemilik (yang pertama = profesi utama); lihat ProfessionLabel (me.yaml).
  final List<String> professions;

  /// Entri teratas riwayat pendidikan (terbaru); null bila kosong.
  final NetworkEducationEntry? latestEducation;

  /// Deprecated (aplikasi 1.0.0); pakai `latest_education`. Institusi entri pendidikan teratas.
  final String? lastEducationInstitution;

  /// Deprecated (aplikasi 1.0.0); kota lulusan terakhir dari aplikasi lama.
  final String? lastEducationCity;

  /// Keahlian (maksimal 10, urut label).
  final List<NetworkMasterRef> skills;

  /// Menulis ke JSON (snake_case); field opsional yang kosong tidak dikirim.
  Map<String, Object?> toJson() => <String, Object?>{
    'user_id': userId,
    'full_name': fullName,
    'avatar_url': ?avatarUrl,
    'cohort': cohort,
    'cohort_code': cohortCode,
    'city': ?city,
    if (profession case final v?) 'profession': v.toJson(),
    'professions': professions,
    'latest_education': encodeNullable(latestEducation, (v) => v.toJson()),
    'last_education_institution': ?lastEducationInstitution,
