          other.cohort == cohort &&
          other.cohortCode == cohortCode &&
          other.city == city &&
          other.profession == profession &&
          deepEquals(other.professions, professions) &&
          other.latestEducation == latestEducation &&
          other.lastEducationInstitution == lastEducationInstitution &&
          other.lastEducationCity == lastEducationCity &&
          deepEquals(other.skills, skills);

  @override
  int get hashCode => Object.hashAll(<Object?>[userId, fullName, avatarUrl, cohort, cohortCode, city, profession, deepHash(professions), latestEducation, lastEducationInstitution, lastEducationCity, deepHash(skills)]);

  @override
  String toString() => 'DirectoryMember(userId: $userId, fullName: $fullName, avatarUrl: $avatarUrl, cohort: $cohort, cohortCode: $cohortCode, city: $city, profession: $profession, professions: $professions, latestEducation: $latestEducation, lastEducationInstitution: $lastEducationInstitution, lastEducationCity: $lastEducationCity, skills: $skills)';
