          other.profession == profession &&
          deepEquals(other.professions, professions) &&
          deepEquals(other.skills, skills) &&
          deepEquals(other.education, education) &&
          other.lastEducationInstitution == lastEducationInstitution &&
          other.lastEducationCity == lastEducationCity &&
          other.bio == bio &&
          other.email == email &&
          other.phone == phone &&
          other.social == social &&
          deepEquals(other.socialLinks, socialLinks) &&
          other.isMe == isMe &&
          other.isBlockedByMe == isBlockedByMe &&
          other.canMessage == canMessage &&
          other.directRoomId == directRoomId;

  @override
  int get hashCode => Object.hashAll(<Object?>[userId, fullName, avatarUrl, cohort, cohortCode, graduationYear, city, profession, deepHash(professions), deepHash(skills), deepHash(education), lastEducationInstitution, lastEducationCity, bio, email, phone, social, deepHash(socialLinks), isMe, isBlockedByMe, canMessage, directRoomId]);

