/// pengungkapan serta deletion_token. Tidak memberi sesi atau akses lain.
@immutable
class WebDeletionVerification {
  const WebDeletionVerification({
    required this.emailMasked,
    required this.deletable,
    required this.registrationPending,
    required this.blockedReason,
    required this.deletion,
    required this.disclosure,
    required this.deletionToken,
    required this.deletionTokenExpiresAt,
  });

  /// Membaca dari JSON (snake_case). Properti yang belum dikenal diabaikan (kompatibilitas maju).
  factory WebDeletionVerification.fromJson(Map<String, Object?> json) {
    return WebDeletionVerification(
      emailMasked: readField(json, 'email_masked', decodeString),
      deletable: readField(json, 'deletable', decodeBool),
      registrationPending: readField(json, 'registration_pending', decodeBool),
      blockedReason: readOptionalField(json, 'blocked_reason', (Object? v0) => WebDeletionVerificationBlockedReason.fromJson(decodeString(v0))),
      deletion: readOptionalField(json, 'deletion', (Object? v0) => AccountDeletion.fromJson(decodeObject(v0))),
      disclosure: readOptionalField(json, 'disclosure', (Object? v0) => AccountDeletionDisclosure.fromJson(decodeObject(v0))),
      deletionToken: readOptionalField(json, 'deletion_token', decodeString),
